/** Record one diagnostic, evicting the oldest retained entry once at capacity. */
record(diagnostic: Diagnostic): void {
  if (this.#entries.length >= this.#capacity) {
    this.#entries.shift();
    this.#droppedCount += 1;
  }
  this.#entries.push(diagnostic);
}

